    // Using built-in if available (Go 1.9+)
    // return uint64(bits.OnesCount64(x))

    // Fallback implementation
    x -= (x >> 1) & 0x5555555555555555
    x = (x>>2)&0x3333333333333333 + x&0x3333333333333333
